<?php $units=$pdo->query('SELECT id,unit_code,unit_name,location,qr_token FROM units ORDER BY unit_code')->fetchAll(); ?>
<div class="card panel"><h3>QR Code Unit</h3><p class="muted">QR mengarah ke kartu identitas unit. Cetak lalu tempel pada kabin atau body unit.</p><div class="qr-grid"><?php foreach($units as $u):?><div class="qr-card"><div id="qr-<?=$u['id']?>"></div><strong><?=e($u['unit_code'])?></strong><span><?=e($u['unit_name'])?></span><small><?=e($u['location'])?></small><button class="btn" onclick="window.print()">Cetak</button></div><?php endforeach;?></div></div>
<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script><?php foreach($units as $u):?>new QRCode(document.getElementById('qr-<?=$u['id']?>'),{text:location.origin+location.pathname.replace('dashboard.php','public-unit.php')+'?token=<?=e($u['qr_token'])?>',width:120,height:120});<?php endforeach;?></script>
